import { MeshPhysicalNodeMaterial, MeshBasicNodeMaterial, DirectionalLight } from 'three/webgpu';
import { gsap } from 'gsap';

export default function createNode(config, ctx) {
  const { THREE } = ctx;
  const { Group, BoxGeometry, PlaneGeometry, Color, Mesh } = THREE;

  const colors = config.intent?.visualSpec?.colors ?? {
    ink: '#16161d',
    paper: '#e8ecf2',
    accent: '#ff2a38',
    surface: '#0b0b10',
  };

  const root = new Group();
  root.name = 'hub-journal-card-0-label';

  // ---- text bridging idiom ----
  const items = config.textContent ?? config.intent?.visualSpec?.textContent ?? [];
  const headlineItem = items.find((i) => i.role === 'headline') ?? { text: 'Journal 3' };
  const labelText = headlineItem.text ?? 'Journal 3';
  const fontSize = headlineItem.typography?.fontSize ?? 39;

  // ---- dimensions ----
  const cardWidth = 1.6;
  const cardHeight = 0.5;
  const cardDepth = 0.06;

  // ---- base card plate (machined metal, roughness/metalness within spec) ----
  const cardGeo = new BoxGeometry(cardWidth, cardHeight, cardDepth, 1, 1, 1);
  const cardMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.ink),
    roughness: 0.55,
    metalness: 0.45,
    clearcoat: 0.2,
    clearcoatRoughness: 0.4,
  });
  const cardMesh = new Mesh(cardGeo, cardMat);
  root.add(cardMesh);

  // ---- accent edge frame (hidden until hover/focus, <=10% frame area) ----
  const frameGeo = new BoxGeometry(cardWidth + 0.045, cardHeight + 0.045, cardDepth * 0.6);
  const frameMat = new MeshPhysicalNodeMaterial({
    color: new Color(colors.accent),
    emissive: new Color(colors.accent),
    emissiveIntensity: 0.0,
    roughness: 0.5,
    metalness: 0.3,
  });
  const frameMesh = new Mesh(frameGeo, frameMat);
  frameMesh.position.z = -0.02;
  root.add(frameMesh);

  // ---- local rim light carrying accent hue (node-local, intensity <= 1.5) ----
  const rimLight = new DirectionalLight(new Color(colors.accent), 0.7);
  rimLight.position.set(-1.2, 0.6, 1.4);
  root.add(rimLight);

  // ---- decorative accent texture corner (from provided asset) ----
  let accentMesh = null;
  const accentSize = 0.24;
  const accentGeo = new PlaneGeometry(accentSize, accentSize);
  const accentMat = new MeshBasicNodeMaterial({
    color: new Color(colors.accent),
    transparent: true,
    opacity: 0.5,
    depthWrite: false,
  });
  accentMesh = new Mesh(accentGeo, accentMat);
  accentMesh.position.set(cardWidth / 2 - accentSize * 0.6, cardHeight / 2 - accentSize * 0.6, cardDepth / 2 + 0.005);
  root.add(accentMesh);

  let accentTexDisposed = false;
  if (config.imageUrl) {
    ctx.textureLoader
      .loadTexture(config.imageUrl)
      .then((tex) => {
        if (accentTexDisposed) return;
        accentMat.map = tex;
        accentMat.needsUpdate = true;
      })
      .catch(() => {});
  }

  // ---- text label ----
  const textNode = ctx.fontAtlas.createText(labelText, {
    fontSize,
    color: colors.paper,
    align: 'center',
  });
  textNode.position.set(0, 0, cardDepth / 2 + 0.006);
  root.add(textNode);

  // ---- apply every configured cinematic primitive (none expected here) ----
  const primitiveHandles = [];
  const primitiveList = config.cinematicPrimitives ?? [];
  for (const prim of primitiveList) {
    const fn = ctx.primitives?.[prim.name];
    if (typeof fn === 'function') {
      const handle = fn(root, prim.params ?? {});
      if (handle) primitiveHandles.push(handle);
    }
  }

  // ---- motion state ----
  const baseY = 0;
  const baseScale = 1;
  let hoverTl = null;
  let pressTl = null;

  function killHoverTl() {
    if (hoverTl) {
      hoverTl.kill();
      hoverTl = null;
    }
  }
  function killPressTl() {
    if (pressTl) {
      pressTl.kill();
      pressTl = null;
    }
  }

  const handlers = {
    onPointerEnter() {
      killHoverTl();
      hoverTl = gsap.timeline();
      hoverTl.to(
        root.position,
        { y: baseY + 0.15, duration: 0.3, ease: 'power2.out' },
        0
      );
      hoverTl.to(
        root.scale,
        { x: 1.03, y: 1.03, z: 1.03, duration: 0.3, ease: 'power2.out' },
        0
      );
      hoverTl.to(
        frameMat,
        { emissiveIntensity: 1.4, duration: 0.3, ease: 'power2.out' },
        0
      );
    },
    onPointerLeave() {
      killHoverTl();
      hoverTl = gsap.timeline();
      hoverTl.to(
        root.position,
        { y: baseY, duration: 0.35, ease: 'power2.out' },
        0
      );
      hoverTl.to(
        root.scale,
        { x: baseScale, y: baseScale, z: baseScale, duration: 0.35, ease: 'power2.out' },
        0
      );
      hoverTl.to(
        frameMat,
        { emissiveIntensity: 0.0, duration: 0.35, ease: 'power2.out' },
        0
      );
    },
    onPointerDown() {
      killPressTl();
      pressTl = gsap.timeline();
      pressTl.to(root.scale, {
        x: 0.97,
        y: 0.97,
        z: 0.97,
        duration: 0.12,
        ease: 'back.out(2)',
      });
    },
    onPointerUp() {
      killPressTl();
      pressTl = gsap.timeline();
      pressTl.to(root.scale, {
        x: 1.0,
        y: 1.0,
        z: 1.0,
        duration: 0.2,
        ease: 'power4.out',
      });
    },
    onClick() {
      ctx.emit('hub-journal.select', { itemId: 'journal-3', target: 'hub-journal-card-0' });
    },
  };

  root.userData.handlers = handlers;

  root.userData.cleanup = () => {
    killHoverTl();
    killPressTl();
    accentTexDisposed = true;

    for (const handle of primitiveHandles) {
      if (handle && typeof handle.cleanup === 'function') handle.cleanup();
    }

    cardGeo.dispose();
    cardMat.dispose();
    frameGeo.dispose();
    frameMat.dispose();
    accentGeo.dispose();
    if (accentMat.map) accentMat.map.dispose?.();
    accentMat.dispose();

    if (typeof textNode.userData?.cleanup === 'function') {
      textNode.userData.cleanup();
    } else {
      textNode.traverse?.((child) => {
        child.geometry?.dispose?.();
        child.material?.dispose?.();
      });
    }

    root.remove(rimLight);
  };

  return root;
}
